#include <vector>
#include <algorithm>
#include <omp.h>

/* Compute the highest node degree in the undirected graph.
   The graph is defined by the adjacency matrix A stored in row‑major order.
   A is an NxN matrix (N = number of vertices). The function works correctly
   for any number of OpenMP threads.
*/
int maxDegree(const std::vector<int>& A, size_t N)
{
    if (N == 0) return 0;               // empty graph

    int maxDeg = 0;                     // will hold the global maximum

    // Parallel loop over rows (vertices).  The reduction clause guarantees
    // that the maximum is computed correctly regardless of the thread count.
    #pragma omp parallel for reduction(max:maxDeg) schedule(static)
    for (size_t i = 0; i < N; ++i) {
        int rowDeg = 0;
        size_t rowStart = i * N;
        for (size_t j = 0; j < N; ++j) {
            rowDeg += A[rowStart + j];
        }
        // The reduction clause updates maxDeg atomically across threads.
        if (rowDeg > maxDeg) {
            maxDeg = rowDeg;
        }
    }

    return maxDeg;
}
